    let driver = await new Builder().forBrowser('chrome').build();
    try {
        await driver.get('https://example.com');
        const results = await new AxeBuilder(driver).analyze();
        console.log(JSON.stringify(results, null, 2));
    } finally {
        await driver.quit();
    }
}

runAxeScan();

